{
  "name": "opencode-tmux-status",
  "version": "0.1.0",
  "private": true,
  "packageManager": "npm@11.17.0",
  "type": "module",
  "description": "Live per-window tmux indicators for OpenCode V2",
  "license": "MIT",
  "author": "Mohammad Alavi",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MaidenAl/opencode_tmux_plugin.git"
  },
  "homepage": "https://github.com/MaidenAl/opencode_tmux_plugin#readme",
  "bugs": {
    "url": "https://github.com/MaidenAl/opencode_tmux_plugin/issues"
  },
  "keywords": ["opencode", "tmux", "plugin", "terminal", "status"],
  "exports": {
    "./tui": "./src/tui.ts"
  },
  "scripts": {
    "test": "node --test test/*.test.ts",
    "test:runtime": "node --test test/runtime.ts",
    "tmux:uninstall": "node src/uninstall.ts",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.6 <3",
    "solid-js": "^1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.6",
    "@types/node": "^24.0.0",
    "solid-js": "^1.9.0",
    "typescript": "~5.9.3"
  },
  "engines": {
    "node": ">=24"
  }
}
